// Scenario controls (toggle via global context or defaults)
const isLeak = flow.get('isLeak') || false;
const isContaminated = flow.get('isContaminated') || false;

// 1. Tank Ultrasonic Metrics (HC-SR04)
const distance_cm = isLeak ? 8.5 : (6.0 + Math.random() * 0.2);
const water_level_percent = Math.round(((30.0 - distance_cm) / 30.0) * 1000) / 10;

// 2. Dual Flow Sensors (YF-S201)
const flow_1_lpm = 10.0 + (Math.random() * 0.4 - 0.2);
const flow_2_lpm = isLeak ? (6.8 + (Math.random() * 0.4 - 0.2)) : (flow_1_lpm - 0.1);

// 3. Water Quality (TDS & Turbidity)
const tds_ppm = isContaminated ? (720.0 + Math.random() * 30) : (125.0 + Math.random() * 10);
const turbidity_raw = isContaminated ? 3400 : 1050;

// Section 11 Unified JSON Schema
msg.payload = {
    "device_id": "ESP32_TANK_01",
    "timestamp": new Date().toISOString(),
    "tank": {
        "distance_cm": Math.round(distance_cm * 10) / 10,
        "water_level_percent": water_level_percent
    },
    "flow": {
        "flow_1_lpm": Math.round(flow_1_lpm * 10) / 10,
        "flow_2_lpm": Math.round(flow_2_lpm * 10) / 10,
        "flow_1_total_liters": 145.2,
        "flow_2_total_liters": 140.8
    },
    "water_quality": {
        "tds_ppm": Math.round(tds_ppm * 10) / 10,
        "turbidity_raw": turbidity_raw
    },
    "pump": {
        "status": true
    },
    "device": {
        "wifi_rssi": -52,
        "firmware_version": "0.1.0"
    }
};

msg.headers = {
    "Content-Type": "application/json"
};

return msg;
